using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // and seeded PK values must be fixed (no dynamic values like DateTime.UtcNow).
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=xyz",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: EF Core 9 Cosmos provider now uses "$type" instead of
        // "Discriminator" for the discriminator property by default.
        // Fix: Explicitly configure the discriminator to keep using "Discriminator"
        // so existing documents remain readable without data migration.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscontinuedProduct>("DiscontinuedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

class DiscontinuedProduct : Product
{
    public DateTime DiscontinuedOn { get; set; }
}

// --- Cosmos DB query service demonstrating sync→async fix ---

class CosmosQueryService
{
    // Breaking change #2: EF Core 9 Cosmos provider no longer supports synchronous I/O.
    // Calls like .ToList(), .First(), .Count() throw InvalidOperationException.
    // Fix: Convert all sync queries to their async equivalents.

    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        // Before (EF Core 8): db.Products.Where(p => p.Category == "Books").ToList();
        return await db.Products
            .Where(p => p.Category == "Books")
            .ToListAsync();
    }

    async Task<Product?> GetFirstProductAsync(CosmosDbContext db)
    {
        // Before (EF Core 8): db.Products.FirstOrDefault(p => p.Name == "Foo");
        return await db.Products
            .FirstOrDefaultAsync(p => p.Name == "Foo");
    }
}

